function selectAuthoringRows(rows) {
  return Object.entries(PURPOSE_COUNTS).flatMap(([purpose, count]) => {
    const selected = rows.filter((item) => item.purpose === purpose).slice(0, count);
    if (selected.length !== count) throw new Error(`Not enough ${purpose} rows`);
    return selected;
  });
}

