function assertDefinitions() {
  for (const [officialCode, definition] of Object.entries(DEFINITIONS)) {
    if (definition.rows?.length !== 40) throw new Error(`${officialCode} must have 40 authored rows`);
    const purposeCounts = Object.groupBy(definition.rows, (item) => item.purpose);
    for (const [purpose, expected] of Object.entries(PURPOSE_COUNTS)) {
      if ((purposeCounts[purpose]?.length ?? 0) !== expected) throw new Error(`${officialCode} purpose ${purpose} count mismatch`);
    }
  }
}

function readJson(relativePath) {
  return JSON.parse(fs.readFileSync(path.join(ROOT, relativePath), 'utf8'));
}

function readSource(officialCode) {
  const source = readJson(SOURCE_PATH);
  const record = source.records?.find((item) => item.officialCode === officialCode);
  if (!record) throw new Error(`Missing source verification for ${officialCode}`);
  if (record.technicalVerificationStatus !== 'OFFICIAL_SOURCE_VERIFIED_EXACT') throw new Error(`Source is not exact for ${officialCode}`);
  return record;
}

function buildQuestions(definition) {
  return definition.rows.map((item, index) => {
    const options = [...item.distractors];
    const answerPosition = index % POSITION_LABELS.length;
    options.splice(answerPosition, 0, item.correctAnswer);
    return {
      id: `${definition.contentId}-${String(index + 1).padStart(2, '0')}`,
      statement: item.statement,
      prompt: item.statement,
      options,
      correctAnswer: item.correctAnswer,
      answerPosition: POSITION_LABELS[answerPosition],
      purpose: item.purpose,
      difficulty: item.difficulty,
      cognitiveProcess: item.cognitiveProcess,
      contextFamily: item.contextFamily,
      explanation: item.explanation,
      hint: item.hint,
      errorFocus: item.errorFocus,
      feedback: { correct: `Boa análise: ${item.explanation}`, incorrect: item.explanation, hint: item.hint, errorFocus: item.errorFocus },
      accessibility: { textOnly: true, supports: ['LEITURA_ORAL', 'ALTO_CONTRASTE', 'TEMPO_FLEXIVEL', 'RESPOSTA_MULTIMODAL'] },
      authored: true,
    };
  });
}

function buildPack(officialCode) {
  const definition = DEFINITIONS[officialCode];
  if (!definition) throw new Error(`No real authoring definition for ${officialCode}`);
  const source = readSource(officialCode);
  const questions = buildQuestions(definition);
  const progression = [
    { phase: 'PROBE', questionIds: questions.filter((item) => item.purpose === 'PROBE').map((item) => item.id) },
    { phase: 'PRACTICE', questionIds: questions.filter((item) => item.purpose === 'PRACTICE').map((item) => item.id) },
    { phase: 'TRANSFER', questionIds: questions.filter((item) => item.purpose === 'TRANSFER').map((item) => item.id) },
    { phase: 'LOCK_IN', questionIds: questions.filter((item) => item.purpose === 'LOCK_IN').map((item) => item.id) },
    { phase: 'REVIEW', questionIds: questions.filter((item) => item.purpose === 'REVIEW').map((item) => item.id) },
  ];
  return {
    packVersion: 'tec-escola-core-v5-question-first',
    contentVersion: 1,
    lessonVersion: 1,
    contentId: definition.contentId,
    canonicalSkillCode: definition.canonicalSkillCode,
    subject: definition.subject,
    domain: definition.domain,
    topic: definition.topic,
    databasePackId: 'TECESCOLA_CORE_V5_QUESTION_FIRST',
    officialMappingStatus: 'NOT_CLAIMED',
    pedagogicalReviewStatus: 'PEDAGOGICAL_REVIEW_PENDING',
    publicationStatus: 'STAGING_INACTIVE',
    active: false,
    contentAuthoringStatus: 'AUTHORED',
    expectedPurposeCounts: PURPOSE_COUNTS,
    expectedQuestionCount: 40,
    expectedContextCount: 40,
    expectedAnswerPositionCounts: { A: 10, B: 10, C: 10, D: 10 },
    sourceContext: {
      officialCode,
      relation: 'AUTHORING_CONTEXT_ONLY',
      mappingStatus: 'CANONICAL_GAP',
      sourceStatus: source.technicalVerificationStatus,
      descriptor: source.descriptor,
      officialSource: source.officialSource,
      note: 'Descritor oficial usado como contexto de autoria; vínculo canônico, revisão pedagógica e publicação permanecem pendentes.',
    },
    sourceReconciliation: { sourceQuestionCount: 0, feedbackAdded: 0, sourceReconciliationStatus: 'NO_SOURCE_QUESTION_REUSED', newQuestions: questions.length, reusedQuestionsCountedAsNew: false },
    lesson: {
      title: definition.title,
      objective: definition.objective,
      summary: definition.summary,
      explanation: definition.explanation,
      workedExample: definition.workedExample,
      commonMistake: definition.commonMistake,
      tips: definition.tips,
      priorKnowledge: definition.priorKnowledge,
      keyConcepts: definition.keyConcepts,
      progression,
      microExplanations: definition.microExplanations,
      remediations: definition.remediations,
      authenticActivities: definition.authenticActivities,
      estimatedMinutes: definition.estimatedMinutes,
      reviewWindowsDays: [1, 3, 7],
      reviewScheduleStatus: 'SUGGESTED_NOT_AUTOMATED',
      sourceDossier: [{ officialCode, descriptor: source.descriptor, officialSource: source.officialSource, checkedAt: source.evidenceCheckedAt, relation: 'AUTHORING_CONTEXT_ONLY' }],
      copyrightNote: 'Material autoral criado para demonstração; o descritor oficial é referenciado como fonte de contexto e não é reproduzido como conteúdo de exercício.',
    },
    questions,
  };
}

function validatePack(pack) {
  const errors = [];
  const questions = pack?.questions ?? [];
  if (pack?.sourceContext?.officialCode === undefined) errors.push('missing source code');
  if (pack?.sourceContext?.relation !== 'AUTHORING_CONTEXT_ONLY') errors.push('invalid source relation');
  if (pack?.officialMappingStatus !== 'NOT_CLAIMED') errors.push('mapping must remain NOT_CLAIMED');
  if (pack?.publicationStatus !== 'STAGING_INACTIVE' || pack?.active !== false) errors.push('pack must remain inactive staging');
  if (pack?.contentAuthoringStatus !== 'AUTHORED') errors.push('content authoring status missing');
  if (questions.length !== 40) errors.push(`expected 40 questions, got ${questions.length}`);
  const ids = new Set(questions.map((item) => item.id));
  if (ids.size !== questions.length) errors.push('question ids must be unique');
  const purposeCounts = Object.groupBy(questions, (item) => item.purpose);
  for (const [purpose, expected] of Object.entries(PURPOSE_COUNTS)) if ((purposeCounts[purpose]?.length ?? 0) !== expected) errors.push(`${purpose} count mismatch`);
  const positionCounts = Object.groupBy(questions, (item) => item.answerPosition);
  for (const position of POSITION_LABELS) if ((positionCounts[position]?.length ?? 0) !== 10) errors.push(`${position} answer position count mismatch`);
  for (const question of questions) {
    if (!question.prompt || question.options?.length !== 4 || !question.correctAnswer || !question.feedback?.correct || !question.feedback?.incorrect || !question.feedback?.hint || !question.feedback?.errorFocus) errors.push(`incomplete question ${question.id}`);
    if (question.options?.filter((option) => option === question.correctAnswer).length !== 1) errors.push(`answer integrity ${question.id}`);
    if (question.authored !== true) errors.push(`question not authored ${question.id}`);
  }
  if (pack?.lesson?.authenticActivities?.length < 2) errors.push('at least two authentic activities required');
  if (!pack?.lesson?.objective || !pack.lesson.explanation || !pack.lesson.workedExample || !pack.lesson.commonMistake || !pack.lesson.remediations?.length || !pack.lesson.microExplanations?.length) errors.push('lesson authoring fields incomplete');
  return { valid: errors.length === 0, errors, questionCount: questions.length, purposeCounts, positionCounts };
}

function writePack(pack) {
  const outputPath = path.join(ROOT, OUTPUT_DIR, DEFINITIONS[pack.sourceContext.officialCode].output);
  fs.mkdirSync(path.dirname(outputPath), { recursive: true });
  fs.writeFileSync(outputPath, `${JSON.stringify(pack, null, 2)}\n`, 'utf8');
  return outputPath;
}

function main() {
  assertDefinitions();
  const checkOnly = process.argv.includes('--check');
  const requested = process.argv.slice(2).filter((arg) => !arg.startsWith('--'));
  const codes = requested.length ? requested : Object.keys(DEFINITIONS);
  for (const officialCode of codes) {
    const pack = buildPack(officialCode);
    const validation = validatePack(pack);
    if (!validation.valid) throw new Error(`${officialCode}: ${validation.errors.join('; ')}`);
    const outputPath = path.join(ROOT, OUTPUT_DIR, DEFINITIONS[officialCode].output);
    if (!checkOnly) writePack(pack);
    else if (!fs.existsSync(outputPath) || fs.readFileSync(outputPath, 'utf8') !== `${JSON.stringify(pack, null, 2)}\n`) throw new Error(`${officialCode}: generated pack is stale`);
    console.log(`${officialCode} ${checkOnly ? 'VALID' : 'WRITTEN'} questions=${validation.questionCount} staging=inactive mapping=NOT_CLAIMED`);
  }
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) main();

const listDefinitions = () => Object.keys(DEFINITIONS);

export { buildPack, validatePack, writePack, listDefinitions };
